// range.
func (c *Core) CKSPLookback(optInTimePeriod int, optInMultiplier float64, optInStopPeriod int) (int, error) {
	if !fitsInt32(optInTimePeriod) {
		return 0, BadParam
	}
	if !fitsInt32(optInStopPeriod) {
		return 0, BadParam
	}
	lookback := c.ckspLookback(int32(optInTimePeriod), optInMultiplier, int32(optInStopPeriod))
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

